"""远程 Agent 管理端点（``/api/v1/agents``）。"""

from __future__ import annotations

import uuid

from fastapi import APIRouter, Query, Response, status

from app.core.deps import AdminUser, CurrentUser, DbSession
from app.modules.agents import service
from app.modules.agents.schemas import (
    AgentCreateRequest,
    AgentDetailOut,
    AgentHealthResult,
    AgentPage,
    AgentPreviewRequest,
    AgentPreviewResult,
    AgentRefreshResult,
    AgentUpdateRequest,
)

router = APIRouter(prefix="/agents", tags=["agents"])


@router.post("/preview", response_model=AgentPreviewResult)
async def preview_agent(payload: AgentPreviewRequest, user: CurrentUser) -> AgentPreviewResult:
    """拉取并校验 Agent Card；不落库。"""
    del user
    return await service.preview_agent(payload)


@router.post("", response_model=AgentDetailOut, status_code=status.HTTP_201_CREATED)
async def create_agent(
    payload: AgentCreateRequest, db: DbSession, admin: AdminUser
) -> AgentDetailOut:
    """注册远程 Agent（仅管理员）；同 url+slug 幂等返回已有记录。"""
    return await service.create_agent(db, admin, payload)


@router.get("", response_model=AgentPage)
async def list_agents(
    db: DbSession,
    user: CurrentUser,
    health_status: str | None = Query(default=None, max_length=16),
    enabled: bool | None = Query(default=None),
    q: str | None = Query(default=None, max_length=100),
    limit: int = Query(default=20, ge=1, le=100),
    cursor: str | None = Query(default=None, max_length=500),
) -> AgentPage:
    del user
    return await service.list_agents(
        db, health_status=health_status, enabled=enabled, q=q, limit=limit, cursor=cursor
    )


@router.get("/{agent_id}", response_model=AgentDetailOut)
async def get_agent(agent_id: uuid.UUID, db: DbSession, user: CurrentUser) -> AgentDetailOut:
    del user
    return await service.get_agent(db, agent_id)


@router.patch("/{agent_id}", response_model=AgentDetailOut)
async def update_agent(
    agent_id: uuid.UUID,
    payload: AgentUpdateRequest,
    db: DbSession,
    admin: AdminUser,
) -> AgentDetailOut:
    return await service.update_agent(db, admin, agent_id, payload)


@router.delete("/{agent_id}", status_code=status.HTTP_204_NO_CONTENT)
async def delete_agent(agent_id: uuid.UUID, db: DbSession, admin: AdminUser) -> Response:
    await service.delete_agent(db, admin, agent_id)
    return Response(status_code=status.HTTP_204_NO_CONTENT)


@router.post("/{agent_id}/refresh", response_model=AgentRefreshResult)
async def refresh_agent(
    agent_id: uuid.UUID, db: DbSession, admin: AdminUser
) -> AgentRefreshResult:
    return await service.refresh_agent(db, admin, agent_id)


@router.post("/{agent_id}/health", response_model=AgentHealthResult)
async def health_check_agent(
    agent_id: uuid.UUID, db: DbSession, admin: AdminUser
) -> AgentHealthResult:
    return await service.health_check_agent(db, admin, agent_id)

def _looks_like_obfuscated_ip(host: str) -> bool:
    """``ipaddress`` 不认、但浏览器可能等价解释为 IPv4 的写法。"""
    return bool(_NUMERIC_HOST_RE.fullmatch(host)) or host.startswith("0x")


def _blocked_ip_reason(ip: ipaddress.IPv4Address | ipaddress.IPv6Address) -> str:
    """返回 IP 字面量的拒绝原因；公网地址返回空串。"""
    if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped is not None:
        ip = ip.ipv4_mapped
    # 顺序有意义：Python 3.13 的 is_private 同时覆盖回环/链路本地，先给出更精确原因。
    if ip.is_unspecified:
        return "unspecified_ip"
    if ip.is_loopback:
        return "loopback_ip"
    if ip.is_link_local:
        return "link_local_ip"
    if ip.is_multicast:
        return "multicast_ip"
    if ip.is_reserved:
        return "reserved_ip"
    if ip.is_private:
        return "private_ip"
    return ""


def _normalize_allowed_hosts(allowed_hosts: list[str]) -> set[str]:
    return {
        unquote(item.strip()).lower().rstrip(".")
        for item in allowed_hosts
        if isinstance(item, str) and item.strip()
    }


def _host_rejection_reason(host: str, *, dev_like: bool) -> str:
    """主机白名单校验：返回拒绝原因；通过返回空串。"""
    if not host:
        return "empty_host"
    if _invalid_host_chars(host):
        return "invalid_host"
    if _has_non_ascii(host):
        return "non_ascii_host"
    # dev/test 的本地回环例外只覆盖精确的 localhost / 127.0.0.1。
    if dev_like and host in _DEV_HTTP_HOSTS:
        return ""
    if host == "localhost":
        return "localhost_host"
    for suffix, reason in _LOCAL_SUFFIXES:
        if host.endswith(suffix):
            return reason

    try:
        ip = ipaddress.ip_address(host)
    except ValueError:
        ip = None
    if ip is not None:
        return _blocked_ip_reason(ip)
    if _looks_like_obfuscated_ip(host):
        return "obfuscated_ip"
    if "." not in host:
        return "single_label_host"
    return ""


def evaluate_authorization_url(
    value: object, *, env: str, allowed_hosts: list[str]
) -> tuple[str | None, str]:
    """校验 ``authorization_url``，返回 ``(可用值或 None, 拒绝原因)``。

    非字符串值（远程 metadata 不可信）按 ``invalid_url`` 拒绝，绝不做 ``str()`` 后
    当成正常 URL 使用。合法时原因为空串；调用方可用原因写审计/日志。校验过程不联网。
    """
    if value is None:
        return None, "blank"
    if not isinstance(value, str):
        return None, "invalid_url"
    stripped = value.strip()
    if not stripped:
        return None, "blank"
    if len(stripped) > MAX_AUTHORIZATION_URL_LENGTH:
        return None, "too_long"
    # 反斜杠会被部分浏览器等价为路径分隔符（如 https://host\/@evil.com），直接拒绝。
    if "\\" in stripped:
        return None, "backslash"
    try:
        parsed = urlsplit(stripped)
    except ValueError:
        return None, "invalid_url"

    scheme = parsed.scheme.lower()
    host = _normalize_host(parsed.hostname)
    dev_like = env in _DEV_ENVS
    dev_local_host = host in _DEV_HTTP_HOSTS
    if scheme == "https":
        pass
    elif scheme == "http" and dev_like and dev_local_host:
        pass
    elif scheme in {"http", "https"}:
        return None, "non_https"
    else:
        return None, "unsupported_scheme"

    if parsed.username is not None or parsed.password is not None:
        return None, "credentials_in_url"
    host_reason = _host_rejection_reason(host, dev_like=dev_like)
    if host_reason:
        return None, host_reason

    allowed = _normalize_allowed_hosts(allowed_hosts)
    if allowed and host not in allowed:
        return None, "host_not_allowlisted"
    return stripped, ""


def validate_authorization_url(
    value: str | None, *, env: str, allowed_hosts: list[str]
) -> str | None:
    """返回可安全展示的 ``authorization_url``；违规返回 ``None``（不抛错）。

    调用方负责记录 warning/审计；展示层（历史脏数据）只过滤、不写审计。
    """
    return evaluate_authorization_url(value, env=env, allowed_hosts=allowed_hosts)[0]


def redact_url_for_audit(value: str, *, limit: int = 200) -> str:
    """生成审计用的 URL 前缀：去控制字符、截断到 ``limit``，并抹掉 userinfo 凭据。

    不依赖 ``urlsplit`` 成功：畸形 URL（如 ``https://user:pass@[::1``）也会先剥离
    userinfo，保证 warning 日志与审计 detail 绝不出现 ``user:pass@``。
    """
    cleaned = _CONTROL_CHARS_RE.sub("", value.strip())
    cleaned = _URL_USERINFO_RE.sub("//", cleaned)
    cleaned = _USERPASS_RE.sub("", cleaned)
    try:
        parsed = urlsplit(cleaned)
    except ValueError:
        return cleaned[:limit]
    if parsed.username is not None or parsed.password is not None:
        netloc = parsed.netloc.rsplit("@", 1)[-1]
        cleaned = urlunsplit((parsed.scheme, netloc, parsed.path, parsed.query, parsed.fragment))
    return cleaned[:limit]


__all__ = [
    "MAX_AUTHORIZATION_URL_LENGTH",
    "evaluate_authorization_url",
    "redact_url_for_audit",
    "validate_authorization_url",
]

